//! ⚠️ Original paid fault admission preserves the retained page and every caller receipt axis.
use semio_framework_job::*;
#[path="../../../🧪️testing/📬️payload/🦀️.rs"]
mod original_payload;
#[global_allocator]
static ORIGINAL_FAULT_HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
#[test]
fn original_fault_binding_keeps_actual_page_and_same_spent_recipient_without_clock(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let operation=OperationId(72031);let generation=Generation(5);let mut original=original_payload::OriginalTestPayload::admit(operation,generation,JobPayloadStream::Fault,&[91],JOB_PAYLOAD_PAGE_BYTES);let payload=original.builder.published().unwrap();let header=payload as*const RetainedJobPayload;let page=payload.page(0).unwrap().as_ptr();
 for row in law["cases"].as_array().unwrap(){let g=row["grant"].as_array().unwrap();let grant=RetainedCloneGrant{maximum_items:g[0].as_u64().unwrap()as usize,maximum_copy_bytes:g[1].as_u64().unwrap()as usize,maximum_capacity_bytes:g[2].as_u64().unwrap()as usize,maximum_release_bytes:g[3].as_u64().unwrap()as usize,maximum_depth:g[4].as_u64().unwrap()as usize};let p=row["prior"].as_array().unwrap();let prior=RetainedCloneProgress{copied_items:p[0].as_u64().unwrap()as usize,copied_bytes:p[1].as_u64().unwrap()as usize,retained_capacity_bytes:p[2].as_u64().unwrap()as usize,released_bytes:p[3].as_u64().unwrap()as usize};let mut recipient=prior;let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||JobOutcomeBorrow::admit_original_fault(operation,generation,grant,&mut recipient,payload));assert_eq!(heap,semio_framework_trace::HeapAllocationObservation::default());assert_eq!(result.is_err(),row["refused"].as_bool().unwrap());let outcome=result.ok().flatten();assert_eq!(outcome.is_some(),row["admitted"].as_bool().unwrap());let admitted=outcome.is_some();if let Some(outcome)=outcome{let mut descriptor=outcome.into_descriptor();let JobOutcomeView::Fault{detail,..}=descriptor.fault(payload).unwrap()else{panic!("same original fault view")};assert!(std::ptr::eq(detail,header));assert_eq!(detail.page(0).unwrap().as_ptr(),page);let grant=original_payload::SOURCE;assert!(descriptor.acknowledge(grant).progress().fits(grant));}assert_eq!(recipient,RetainedCloneProgress{copied_items:prior.copied_items+usize::from(admitted),..prior});assert_eq!(payload as*const RetainedJobPayload,header);assert_eq!(payload.page(0).unwrap().as_ptr(),page);}
 original.close();assert_eq!(original_payload::observe(||drop(original)).1,(0,0));
}
